{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Alpidem, a close structural analogue with the same N,N-dialkylacetamide and bicyclic heteroaromatic core, easily crosses the BBB in rats with a brain/plasma ratio of about 2.0-2.5 after systemic administration, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The closely related N,N-diethylacetamide analogue [18F]-(R)-TRACK passes the BBB and shows high brain uptake in non-human primates, demonstrating that this chemotype achieves meaningful CNS exposure in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PI1, a brain-penetrant NPSR antagonist with a similar amide-linked heteroaromatic scaffold, is present in good concentrations in rat CSF after intraperitoneal administration, providing direct evidence of CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CNS-11, a high-transfer analogue, showed measurable brain tissue concentrations (5.7-17.8 ng/g) one hour after administration in mice, confirming that this scaffold can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "[11C]MBMP, another high-transfer analogue, showed fast penetration across the BBB into all brain regions within 1 minute of injection in mice, supporting rapid and meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SRN-003-556, a high-transfer analogue, is BBB-permeant in mice with a brain Cmax of 1.8 µM after oral dosing, showing that even a modest logBB (-0.22) can still correspond to meaningful brain exposure in this compound class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: multiple high-transfer analogues with direct in vivo brain penetration measurements (autoradiography, PET, CSF, brain tissue) consistently demonstrate meaningful CNS access for this N,N-dialkylacetamide-substituted bicyclic heteroaromatic chemotype, and the query shares the key structural features responsible for that behavior.",
  "evidence_gaps": [
    "No direct experimental BBB data are available for the exact query molecule.",
    "Efflux transporter liability (e.g., P-gp/BCRP) was not directly measured for the query, although the analogue evidence suggests adequate net brain penetration.",
    "Most evidence comes from rodent or non-human primate studies; human translation is inferred rather than directly demonstrated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

